// HeaderReplicas and HeaderInternalReplicas name the response headers that
// advertise a repo's hosting nodes: the public-mount header and the in-VPC
// svctok-mount header (ADR 20260518). The repo OpenAPI replica-redirect
// (server/repoapi) emits the same headers for the same mounts, so both
// implementations reference these constants to stay in lockstep.
const (
	HeaderReplicas         = "X-Entire-Replicas"
	HeaderInternalReplicas = "X-Entire-Internal-Replicas"
)

// HandleInfoRefsDiscovery sets the replicas header on info/refs responses
// and, when this node does not host the repo, issues a 307 to a hosting
// replica. Returns true if the response has been written (redirect),
// false to fall through to the normal git handler.
//
// Mount-aware per UseInternalAddr (ADR 20260518-internal-h2c-data-plane-access):
//   - Public :443 mount (UseInternalAddr=false): redirects to a public
//     advertise address; emits X-Entire-Replicas; honours the ALB
//     X-Amzn-Trace-Id heuristic to pin clients to a node-specific URL.
//   - Strict-mTLS svctok mount (UseInternalAddr=true): redirects to a
//     peer's HTTPInternalAdvertiseAddr; emits X-Entire-Internal-Replicas;
//     no ALB heuristic (the svctok NLB is L4 + per-connection, so HTTP/2
//     and HTTP/1.1 keep-alive already pin requests to a single node). If
//     no peer has gossiped an internal addr yet (mixed-version cluster
//     mid-rollout), returns false — the caller falls through to the
//     local handler with DissStore-backed object fetch for any objects
//     this node doesn't host.
//
// Caller passes the appropriate addrs slice: HTTPAddrs() for the public
// mount, HTTPInternalAddrs() for the svctok mount.
//
// While the shutdown barrier is up, this node drops itself from the
// candidates, so a repo it hosts redirects instead of being served locally.
// Returns false when it is the only candidate, leaving the caller to reject.
func (s *Service) HandleInfoRefsDiscovery(w http.ResponseWriter, r *http.Request, addrs []string) bool {
	selfAddr := s.HTTPAdvertiseAddr
	headerName := HeaderReplicas
	if s.UseInternalAddr {
		selfAddr = s.HTTPInternalAdvertiseAddr
		headerName = HeaderInternalReplicas
	}
	if selfAddr == "" {
		return false
	}
	if len(addrs) == 0 {
		return false
	}

	// Self is a candidate only while this node will still serve the pack.
	draining := adminapi.IsShuttingDown(s.Shutdown)
	if draining {
		addrs = slices.DeleteFunc(slices.Clone(addrs), func(a string) bool { return a == selfAddr })
		if len(addrs) == 0 {
			return false
		}
	}

	scheme := "https"
	if s.TLSConfig == nil {
		scheme = "http"
	}
	uris := make([]string, len(addrs))
	for i, a := range addrs {
		uris[i] = scheme + "://" + a
	}
	w.Header().Set(headerName, strings.Join(uris, ","))

	// The ALB-pin heuristic is only meaningful behind the public ALB
	// (which itself adds X-Amzn-Trace-Id). The svctok NLB doesn't set
	// this header; on the internal mount we always redirect when this
	// node isn't a provider (and skip when it is — the slices.Contains
	// check below).
	viaALB := !s.UseInternalAddr && r.Header.Get("X-Amzn-Trace-Id") != ""
	if !viaALB && slices.Contains(addrs, selfAddr) {
		return false
	}

	target := uris[rand.IntN(len(uris))] + r.URL.RequestURI() //nolint:gosec // load-spreading, not security

	// Cross-host auth carry-over: libcurl 7.86+ strips Authorization headers
	// set via CURLOPT_HTTPHEADER on cross-origin redirects by default
	// (CURLOPT_UNRESTRICTED_AUTH=0). This nukes git's http.extraHeader bearer
	// when the redirect crosses hosts — exactly our case
	// (svctok.<cluster>.partial.internal:8281 → nodeN.<cluster>.partial.internal:8281).
	//
	// Workaround: embed the bearer into the Location URL as basic-auth
	// password. URL-form credentials are NOT in libcurl's auth-strip set, so
	// they survive every redirect on this request. The svctok git auth
	// middleware (internal/entireserver/svctok_listener.go:svcTokGitAuthMiddleware)
	// already accepts Basic auth and treats the password as the bearer
	// token, so no server-side acceptance change is needed.
	target = EmbedRedirectAuth(target, r.Header.Get("Authorization"))

	http.Redirect(w, r, target, http.StatusTemporaryRedirect)
	return true
}

